\begin{definition}[Gravitation tensor]
\dcref{ch2:1.1}
\label{topping:notn-gravitation-tensor}
\source{topping:page-0028}
\group{topping-background}


For a symmetric $2$-tensor $T$, define
\[
G(T):=T-\frac12(\tr T)g.
\]
\end{definition}

